#AD163713066910.ad-template .col .ad-view { position:relative; } window.googletag = window.googletag || {cmd: []}; googletag.cmd.push(function() { googletag.defineSlot('/21724694934/21835161981/22652325777', [[580, 400], [640, 360]], 'aiin-adincontent-middle').addService(googletag.pubads()).setTargeting('TARGET_INV_ZONE', ['content']).setTargeting('TARGET_CREATIVE', ['ADEXCHANGE_CPM']); googletag.enableServices(); googletag.display('aiin-adincontent-middle'); googletag.pubads().addEventListener('slotRenderEnded', function (event) { if (event.isEmpty == true && event.slot.getSlotId().getName() == '/21724694934/21835161981/22652325777') { var adIns = document.createElement('ins'); adIns.className = "adsbyaiinad"; adIns.setAttribute('data-aiinad-inv', "22652325837"); document.getElementById('aiin-adincontent-middle').append(adIns); } }); }); 무소속 박권현 예비후보. 청도군의원 3선, 경북도의원 3선. 지역 정치사를 통틀어도 좀처럼 찾기 어려운 이력이다. 청도에서 24년. 한 사람이 지역 의정에 쏟아부은 이 시간의 두께는, 단순한 '경력 한 줄'로 요약될 수 있는 성질의 것이 아니다. 박 후보가 의회에서 다룬 누적 예산은 100조 원을 넘어선다. 경북도의회 농수산위원회 부위원장, 문화환경위원회 위원장을 차례로 역임하며 쌓아 올린 예산·정책 전문성은 경북 정가 안에서도 별도의 설명이 필요 없는 수준이다. 지역의 한 원로 정치인은 "박권현은 공부하는 정치인이다. 자료를 들고 밤을 새우는 사람이고, 숫자로 논쟁하는 사람"이라고 평했다. 대륜고, 대구대 경영학과, 영남대 행정대학원. 박 후보가 걸어온 학력과 경력은 화려함보다 성실함에 가깝다. 그러나 그 성실함이 지난 24년간 청도의 예산과 정책 구석구석에 스며들어 있다는 사실은, 청도 군민이라면 몸으로 알고 있는 이야기다. 도로가 놓이고, 다리가 걸리고, 농업 예산이 따내지던 그 자리마다 박권현이라는 이름이 있었다. 박 후보는 최근 출마 선언에서 "저는 군민 여러분께 '약속'이 아니라 '이력'으로 말씀드리겠다"고 했다. 이 한 문장은 이번 선거에서 박 후보가 서 있는 자리를 정확히 보여준다. 그는 공약집을 먼저 내놓지 않았다. 먼저 꺼낸 것은 자신의 걸어온 길, 그리고 그 길에 남은 증거들이었다. 정치 신인의 구호도 아니고, 현직자의 치적 나열도 아닌, 오직 24년의 의정활동 기록 그 자체다. 박 후보가 발표한 '고품질 평생도시 청도' 5대 공약 역시 결이 다르다. 영남권 수출형 푸드테크 특구, 대경선 광역철도 청도역 연장, AI·IT 특성화 학교 설립, 24시간 응급의료 체계, 청도읍성·운문사·신화랑 풍류마을을 잇는 3대 관광 거점. 모두 예산 구조와 중앙부처 협력 동선을 꿰뚫고 있지 않으면 설계 자체가 불가능한 공약들이다. "공약은 꿈이 아니라 예산입니다. 예산이 설명되지 않는 공약은 거짓말입니다." 박 후보가 캠프 내부 회의에서 반복했다는 말이다. 흥미로운 점은 박 후보가 무소속이라는 사실이다. 국민의힘에서 24년동안 당원으로 활동했다. 그 후 2022년 당내 공천 과정의 문제를 지적하며 무소속 출마를 택했던 그는, 이번에도 같은 길을 걷고 있다. 캠프 관계자는 "박 후보의 무소속 출마는 보수 가치로부터의 이탈이 아니라, 납득되지 않는 공천 과정에 대한 정치적 소신의 표현"이라며 "당의 줄보다 군민의 뜻을 먼저 생각하는 사람이라는 것이 박 후보의 일관된 태도"라고 전했다. 지역 정가에서는 이번 청도군수 선거가 사실상 '인물의 검증'으로 귀결될 것이라는 관측이 많다. 현직 프리미엄과 당 공천이라는 외형적 조건을 넘어, 군민들이 실제로 손에 쥘 수 있는 '검증된 능력'과 '품격 있는 리더십'이 어디에 있느냐는 질문이 이번 선거의 본질이라는 것이다. 청도 읍내의 한 자영업자는 "이번에는 누가 더 예산을 따올 수 있느냐, 누가 더 신뢰할 만한 사람이냐로 보고 있다"며 "24년간 지켜본 사람이 있다는 건 군민 입장에서 큰 자산"이라고 말했다. 박 후보는 청도읍·화양읍과 각남면·각북면·풍각면·이서면·운문면·금천면·매전면 등 2읍 7면 전 지역을 빠짐없이 찾겠다고 밝혔다. 특히 가장 작고 고령화율이 가장 높은 각북면까지 군수가 직접 챙기는 행정을 공언했다. "한 면(面)도 소외되지 않는 청도"라는 그의 말은 지난 24년 동안 그가 실제로 걸어온 동선과 겹친다. '체급이 다른 리더십.' 박 후보 캠프가 내건 브랜딩 문구는 단순한 자화자찬이 아니다. 24년의 의정 경험, 100조 원의 예산 심의 이력, 경북도의회 핵심 위원장직 역임. 이 모든 것이 하나의 이름 아래 집약돼 있는 후보는 이번 청도군수 선거에서 박권현이 유일하다. 청도 군민은 지금, 24년 만에 돌아온 '완성형 해결사' 앞에 서 있다. 신선미 기자 sunmi@gokorea.kr 다른기사 저작권자 © 공감신문 무단전재 및 재배포 금지 /**************************************************
