다가오는 6·3 지방선거에서는 함께 힘을 모아 압도적인 승리를 만들어 가자"고 강조했다. 또한 이 예비후보는 "이번 경선 승리를 발판으로 더불어민주당의 승리와 함평의 발전과 변화를 위해 더욱 매진하겠다"며 "군민 기대에 부응하는 책임 있는 후보가 되겠다"고 밝혔다. 이 예비후보는 4월 8일부터 9일까지 이틀간 진행된 경선에서 당원 50%, 일반 군민 50%가 참여한 ARS 투표 결과 최종 1위로 확정됐다. #이남오 # 함평군 # 함평군수 기사이력코드 취재(기획) 취재(기획) 취재(제보) 취재(자료보완) 보도자료 SNS 서핑 기타(국내외 논문·학술지) 기타(증권사 리포트) 기타(타 언론사 후속보도) 메트로신문 양수녕 기자 ysn6313@metroseoul.co.kr 다른기사 보기 Copyright ⓒ 메트로신문 & metroseoul.co.kr function goSearchPage(searchText){ location.href="/search?searchText="+encodeURI(searchText); return; } (function () { $.ajax({ type : "GET", url : "/wps/engine/rest/35?type=COMPONENT", success: function (data) { $("#ZxBejhqxJS").after(data); $("#ZxBejhqxJS").remove(); } }); })() 메트로신문 지면 PDF 보기 // 현재 날짜 구하기 var now = new Date(); // 요일 체크 (0 = 일요일, 1 = 월요일, ..., 6 = 토요일) var dayName = now.getDay(); // 주말이면 금요일 날짜로 바꾸기 if (dayName === 0) { // 일요일이면 now.setDate(now.getDate() - 2); // 금요일로 이동 } else if (dayName === 6) { // 토요일이면 now.setDate(now.getDate() - 1); // 금요일로 이동 } // MMddDate: MMDD 형식 var MMddDate = ("0" + (now.getMonth() + 1)).slice(-2) + ("0" + now.getDate()).slice(-2); // yyyyMMddDate: yyyy/MM/dd 형식 var yyyyMMddDate = now.getFullYear() + "/" + ("0" + (now.getMonth() + 1)).slice(-2) + "/" + ("0" + now.getDate()).slice(-2); // yyyyMMddDate2: yyyy-MM-dd 형식 var yyyyMMddDate2 = now.getFullYear() + "-" + ("0" + (now.getMonth() + 1)).slice(-2) + "-" + ("0" + now.getDate()).slice(-2); // 이미지 src URL 생성 var imageUrl = "https://pdf.metroseoul.co.kr/pdf/" + yyyyMMddDate + "/img/s10/kr_metro_1_" + MMddDate + "_01.jpg"; // HTML 요소에 값 삽입 document.getElementById('pdfImage').setAttribute('src', imageUrl); document.getElementById('pdfDate').textContent = yyyyMMddDate2; (function () { $.ajax({ type : "GET", url : "/wps/engine/rest/46?type=BANNER", success: function (data) { $("#oEUNhoDLeD").after(data); $("#oEUNhoDLeD").remove(); } }); })() (function () { $.ajax({ type : "GET", url : "/wps/engine/rest/29?type=COMPONENT", success: function (data) { $("#DwrbpYHMir